CREATE TABLE public.event_organisers (event_id uuid PRIMARY KEY REFERENCES public.events(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, assigned_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.event_organisers TO authenticated;
GRANT ALL ON public.event_organisers TO service_role;
ALTER TABLE public.event_organisers ENABLE ROW LEVEL SECURITY;
CREATE POLICY organiser_assignments_read ON public.event_organisers FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY organiser_assignments_admin ON public.event_organisers FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE INDEX event_organisers_user_idx ON public.event_organisers(user_id);
ALTER TABLE public.event_registrations ADD COLUMN secret_code text NOT NULL DEFAULT upper(substr(replace(gen_random_uuid()::text,'-',''),1,12));
CREATE UNIQUE INDEX registration_secret_unique ON public.event_registrations(secret_code);
CREATE INDEX registrations_event_created_idx ON public.event_registrations(event_id,created_at,id);
ALTER TABLE public.attendance ADD COLUMN verified_by uuid REFERENCES public.profiles(id), ADD COLUMN verified_at timestamptz;
CREATE OR REPLACE FUNCTION public.is_event_organiser() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.event_organisers WHERE user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_event_organiser() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_event_organiser() TO authenticated;
CREATE OR REPLACE FUNCTION public.can_manage_event(_event_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.event_organisers WHERE event_id=_event_id AND user_id=auth.uid())) $$;
REVOKE ALL ON FUNCTION public.can_manage_event(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_manage_event(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.enforce_participation_credits() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.credits := CASE NEW.category WHEN 'tech' THEN 20 ELSE 15 END; RETURN NEW; END $$;
CREATE TRIGGER fixed_event_credits BEFORE INSERT OR UPDATE ON public.events FOR EACH ROW EXECUTE FUNCTION public.enforce_participation_credits();
CREATE OR REPLACE FUNCTION public.event_roster(_event_id uuid,_search text DEFAULT '',_page integer DEFAULT 0) RETURNS TABLE(registration_id uuid,user_id uuid,roll_number text,full_name text,department text,secret_code text,registered_at timestamptz,present boolean,credits integer,total_count bigint) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT public.can_manage_event(_event_id) THEN RAISE EXCEPTION 'Not assigned to this event'; END IF;
RETURN QUERY SELECT r.id,r.user_id,p.roll_number,p.full_name,p.department,r.secret_code,r.created_at,(a.verified_at IS NOT NULL),coalesce(a.credits,0),count(*) OVER() FROM public.event_registrations r JOIN public.profiles p ON p.id=r.user_id LEFT JOIN public.attendance a ON a.user_id=r.user_id AND a.event_id=r.event_id WHERE r.event_id=_event_id AND (p.roll_number ILIKE '%'||left(_search,80)||'%' OR p.full_name ILIKE '%'||left(_search,80)||'%') ORDER BY r.created_at,r.id LIMIT 50 OFFSET greatest(0,least(_page,100000))*50; END $$;
REVOKE ALL ON FUNCTION public.event_roster(uuid,text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.event_roster(uuid,text,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.verify_event_attendance(_registration_id uuid,_secret_code text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.event_registrations; c integer; was_present boolean; BEGIN
SELECT * INTO r FROM public.event_registrations WHERE id=_registration_id FOR UPDATE;
IF NOT FOUND OR NOT public.can_manage_event(r.event_id) THEN RAISE EXCEPTION 'Not assigned to this event'; END IF;
IF r.secret_code <> upper(trim(_secret_code)) THEN RAISE EXCEPTION 'Registration code does not match'; END IF;
SELECT CASE category WHEN 'tech' THEN 20 ELSE 15 END INTO c FROM public.events WHERE id=r.event_id;
SELECT verified_at IS NOT NULL INTO was_present FROM public.attendance WHERE event_id=r.event_id AND user_id=r.user_id;
IF coalesce(was_present,false) THEN RETURN jsonb_build_object('status','already','credits',c); END IF;
INSERT INTO public.attendance(user_id,event_id,credits,verified_by,verified_at) VALUES(r.user_id,r.event_id,c,auth.uid(),now()) ON CONFLICT(user_id,event_id) DO UPDATE SET credits=excluded.credits,verified_by=excluded.verified_by,verified_at=excluded.verified_at;
RETURN jsonb_build_object('status','ok','credits',c); END $$;
REVOKE ALL ON FUNCTION public.verify_event_attendance(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.verify_event_attendance(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.claim_event_credit(_token uuid) RETURNS json LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT json_build_object('status','verification_required') $$;
CREATE OR REPLACE FUNCTION public.check_registration_ticket(_token uuid) RETURNS TABLE(roll_number text,full_name text,event_title text,registered_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ev uuid; BEGIN SELECT event_id INTO ev FROM public.event_registrations WHERE ticket_token=_token; IF ev IS NULL OR NOT public.can_manage_event(ev) THEN RAISE EXCEPTION 'Not assigned to this event'; END IF; RETURN QUERY SELECT p.roll_number,p.full_name,e.title,r.created_at FROM public.event_registrations r JOIN public.profiles p ON p.id=r.user_id JOIN public.events e ON e.id=r.event_id WHERE r.ticket_token=_token; END $$;
CREATE OR REPLACE FUNCTION public.get_leaderboard() RETURNS TABLE(user_id uuid,roll_number text,full_name text,department text,total integer,tech integer,non_tech integer,events_count integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.roll_number,p.full_name,p.department,coalesce(sum(a.credits),0)::integer,coalesce(sum(a.credits) FILTER(WHERE e.category='tech'),0)::integer,coalesce(sum(a.credits) FILTER(WHERE e.category='non_tech'),0)::integer,count(a.id)::integer FROM public.profiles p LEFT JOIN public.attendance a ON a.user_id=p.id AND a.verified_at IS NOT NULL LEFT JOIN public.events e ON e.id=a.event_id GROUP BY p.id ORDER BY 5 DESC,p.full_name $$;
REVOKE EXECUTE ON FUNCTION public.record_event_winner(uuid,uuid,integer,integer),public.remove_event_winner(uuid),public.finalize_quiz(uuid),public.submit_quiz(uuid,jsonb) FROM PUBLIC,anon,authenticated;
COMMENT ON TABLE public.event_awards IS 'DEPRECATED: participation only; excluded from leaderboard and app';
COMMENT ON TABLE public.event_qr IS 'DEPRECATED: self-claim QR replaced by organiser verified attendance';
COMMENT ON TABLE public.quiz_sessions IS 'DEPRECATED: participation only; no prize tiebreaker';
COMMENT ON TABLE public.quiz_participants IS 'DEPRECATED: participation only';
COMMENT ON TABLE public.quiz_questions IS 'DEPRECATED: participation only';